```tsx
import { useId } from "react";
import "./EmptyState.css";

export interface EmptyStateProps {
  title: string;
  message: string;
  actionLabel: string;
  onAction: () => void;
}

export function EmptyState({ title, message, actionLabel, onAction }: EmptyStateProps) {
  const headingId = useId();

  return (
    <section className="empty-state" aria-labelledby={headingId}>
      <h2 id={headingId} className="empty-state__title">
        {title}
      </h2>
      <p className="empty-state__message">{message}</p>
      <button type="button" className="empty-state__action" onClick={onAction}>
        {actionLabel}
      </button>
    </section>
  );
}
```

```css
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(0.5rem, 1.2vw, 0.9rem);
  padding: clamp(1.5rem, 4vw, 3rem) clamp(1rem, 3vw, 2rem);
  border: 1px solid var(--hair);
  border-radius: 1rem;
  background: var(--code-bg);
  color: var(--ink);
  font: inherit;
  text-align: center;
}

.empty-state__title {
  margin: 0;
  font: inherit;
  font-size: clamp(1.1rem, 2.2vw, 1.5rem);
  font-weight: 600;
  color: var(--ink);
}

.empty-state__message {
  margin: 0;
  max-width: 36ch;
  font: inherit;
  font-size: clamp(0.9rem, 1.6vw, 1.05rem);
  line-height: 1.5;
  color: var(--muted);
}

.empty-state__action {
  margin-top: 0.5rem;
  padding: 0.6rem 1.25rem;
  border: 1px solid var(--myelin);
  border-radius: 999px;
  background: var(--myelin);
  color: var(--slide);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: box-shadow 160ms ease;
}

.empty-state__action:hover {
  box-shadow: 0 0 0 4px var(--myelin-wash);
}

:root[data-motion="reduce"] .empty-state__action {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .empty-state__action {
    transition: none;
  }
}
```

